// Compare optimized presentation against the previous production owners.
// Native glyph/pixel evidence is generated by CONTROL_POLISH_REVIEW.
const assert=require('assert'),vm=require('vm'),{execFileSync}=require('child_process');
const {createRig,load}=require('./check-level-01-boss');
const base=process.env.CONTROL_POLISH_COMPARE_BASE;
const prior=file=>execFileSync('git',['show',`${base}:${file}`],{cwd:require('path').resolve(__dirname,'..'),encoding:'utf8'});
const old=base?createRig():null,fresh=createRig();
if(old)vm.runInContext(prior('src/game/comic-hud.js'),old.context);
const plain=v=>JSON.parse(JSON.stringify(v));
let seed=91;
const rand=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);
function actor(x,y,width,height,onRead=()=>{}){
  return {position:{x,y},getHitbox(){onRead();return{x,y,width,height};}};
}
for(const r of [old,fresh].filter(Boolean)){r.w.gameCamera={centerX:960,y:0};r.w.rhythmSystem.hideRhythmMode();}
for(let scenario=0;old&&scenario<80;scenario++){
  const actors=Array.from({length:scenario%15},()=>actor(-500+rand()*2700,100+rand()*900,40+rand()*170,50+rand()*200));
  const variants=[{width:780,height:710},{width:1040,height:360,compact:true}],owners=[{},{}];
  for(let frame=0;frame<4;frame++){
    const results=[old,fresh].map((r,i)=>{
      r.w.gameState.gameTime=frame*180;
      return plain(r.w.BARCODE.OverlayLayout.present(owners[i],'test',variants,{actors}));
    });
    assert.deepStrictEqual(results[1],results[0],`unchanged smart placement/motion, scene ${scenario}/${frame}`);
    if(actors.length){actors[0].position.x+=120;const a=actors[0];a.getHitbox=()=>({x:a.position.x,y:a.position.y,width:120,height:160});}
  }
}
const projections=[];
for(const r of [old,fresh].filter(Boolean)){
  let count=0;
  const actors=Array.from({length:12},()=>actor(-900,-900,4000,4000,()=>count++));
  const result=r.w.BARCODE.OverlayLayout.present({},'crowded',[{width:1100,height:400},{width:860,height:500},{width:600,height:700}],{actors});
  assert(result.docked);projections.push(count);
}
assert.equal(projections.at(-1),12,'one live projection per actor, shared across variants');
if(old)assert(projections[0]>projections[1]);
function drawing(){
  const labels=[],rects=[],stack=[],state={textBaseline:'top',textAlign:'right',font:'18px monospace',globalAlpha:1};
  const c=new Proxy(state,{get(o,key){
    if(key==='save')return()=>stack.push({...o});
    if(key==='restore')return()=>Object.assign(o,stack.pop());
    if(key==='measureText')return text=>({width:String(text).length*14});
    if(key==='fillText')return(text,x,y)=>labels.push({text,x,y,baseline:o.textBaseline});
    if(key==='fillRect')return(x,y,width,height)=>rects.push({x,y,width,height});
    return key in o?o[key]:()=>{};
  }});return{c,labels,rects};
}
const r=fresh,{w,context,p}=r,m=w.enemyManager;
load(context,'src/core/gamepad-ui.js');p.startMission();w.player.grounded=true;
m.enemies=Array.from({length:12},(_,i)=>{
  const e=new w.Enemy(900+i*10,784,'virus');
  Object.assign(e.position,{x:900+i*10,y:784});
  Object.assign(e,{entranceComplete:true,spawnTimeMs:-10000,spawnProtectionDuration:0});return e;
});
const calls=[],settings=w.BARCODE.ControllerSettings;
for(const [device,binding,expected] of [['keyboard',3,'H'],['xbox',3,'Y'],['playstation',3,'△'],['playstation',7,'R2'],['xbox',5,'RB']]){
  w.BARCODE.GamepadUI.connected=device!=='keyboard';settings.labels=device;settings.bindings.interact=binding;
  let scans=0;const find=m.findHijackTarget;m.findHijackTarget=function(...args){scans++;return find.apply(this,args);};
  const {c,labels,rects}=drawing();m.draw(c);m.findHijackTarget=find;
  assert.equal(scans,1,'one target lookup for the crowd');assert(!m._drawingMarkers&&!m._readyHijackMarker);
  const label=labels.find(l=>l.text===expected);assert(label,`${device}: correct mapped hack prompt`);
  const box=rects.find(b=>b.height===27);assert(box);assert(box.width>=expected.length*14+12);
  assert.equal(label.x,box.x+box.width/2);assert.equal(label.y,box.y+box.height/2);
  assert.equal(label.baseline,'middle','fallback explicitly owns its baseline');
  calls.push({device,binding,label:expected,scans});
}
// A separate draw after movement must select again, including after exceptions.
const nearest=m.findHijackTarget();w.player.position.x=1010;
assert.notStrictEqual(m.findHijackTarget(),nearest);
const draw=m.enemies[0].draw;m.enemies[0].draw=()=>{throw new Error('fixture');};
assert.throws(()=>m.draw(drawing().c),/fixture/);assert(!m._drawingMarkers&&!m._readyHijackMarker);m.enemies[0].draw=draw;
// Text-layout reuse must invalidate when a controller label or dialogue changes.
load(context,'src/game/tutorial.js');const t=new w.TutorialSystem();t.startTutorial();t.startChapter(2);
t.dialogue[0].text+=' {rhythm_mode}'; // Exercise the supported device-aware token.
settings.labels='xbox';settings.bindings.rhythm_mode=4;
let wraps=0;const wrap=t.wrapText;t.wrapText=function(...args){wraps++;return wrap.apply(this,args);};
t.getDialogueLayout();const first=wraps;assert(first>0);t.getDialogueLayout();assert.equal(wraps,first);
settings.labels='playstation';t.getDialogueLayout();assert(wraps>first,'new glyphs invalidate measurements');
const second=wraps;t.dialogue[0].text+=' More words.';t.getDialogueLayout();assert(wraps>second);
t.startTutorial();assert.equal(t._dialogueMeasure,null,'restart releases cached text');
console.log(JSON.stringify({placementComparisons:old?320:0,comparisonBase:base||null,actorProjections:{before:old?projections[0]:null,after:projections.at(-1)},mappedPrompts:calls,tutorialLayoutReuse:'passed',scope:'operation counts; no claim about hosted FPS'},null,2));
